195	    /**
196	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
197	     * source of truth for how an email is persisted, so inputs that differ only in letter case
198	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
199	     * (create and update, mapper or hand-copied) stores the same canonical value.
200	     *
201	     * @param email the raw email, possibly {@code null}
202	     * @return the lower-cased form, or {@code null} if the input was {@code null}
203	     */
204	    public static String normalizeEmail(String email) {
205	        return email == null ? null : email.toLowerCase();
206	    }
207	
208	    /**
209	     * Disposable email domains that are not accepted for an owner. Compared case-insensitively
210	     * against the domain part of the owner's email (see {@link #isDisposableEmailDomain(String)}).
211	     */
212	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
213	        "mailinator.com",
214	        "tempmail.com",
215	        "guerrillamail.com");
216	
217	    /**
218	     * Check whether an email's domain is on the disposable-domain blocklist. The domain is the text
219	     * after the last {@code '@'}, compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}.
220	     * This is the single source of truth for which email domains are rejected, shared by any
221	     * persistence path. A {@code null} or empty email, or one with no {@code '@'}, is not disposable.
222	     *
223	     * @param email the owner's email, possibly {@code null}
224	     * @return {@code true} if the email's domain is on the blocklist, {@code false} otherwise
225	     */
226	    public static boolean isDisposableEmailDomain(String email) {
227	        if (email == null) {
228	            return false;
229	        }
230	        int at = email.lastIndexOf('@');
231	        if (at < 0) {
232	            return false;
233	        }
234	        String domain = email.substring(at + 1).toLowerCase();
235	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
236	    }
237	
238	    /**
239	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
240	     * truth for how a telephone is compared and persisted, so inputs that differ only in
241	     * formatting (spaces, dashes, brackets) are treated as the same number.
242	     *
243	     * <p>The rules are:
244	     * <ul>
245	     *   <li>spaces, dashes and brackets are stripped;</li>
246	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
247	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
248	     *       is dropped from the national digits;</li>
249	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
250	     *   <li>for a recognized country code the national number (the digits after the country
251	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
252	     *       digits and {@code '+1'} requires 10.</li>
253	     * </ul>
254	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
255	     * values are returned unchanged.
256	     *
257	     * @param telephone the raw telephone, possibly {@code null}
258	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
259	     *     valid E.164 number
260	     */
261	    public static String normalizeTelephone(String telephone) {
262	        if (telephone == null) {
263	            return null;
264	        }
265	        String trimmed = telephone.trim();
266	        boolean hasCountryCode = trimmed.startsWith("+");
267	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
268	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
269	        if (hasCountryCode) {
270	            stripped = stripped.substring(1);
271	        }
272	        if (!stripped.matches("\\d+")) {
273	            return null;
274	        }
275	        String digits;
276	        if (hasCountryCode) {
277	            digits = stripped;
278	        } else {
279	            if (stripped.startsWith("0")) {
280	                stripped = stripped.substring(1);
281	            }
282	            digits = "61" + stripped;
283	        }
284	        if (digits.length() < 8 || digits.length() > 15) {
285	            return null;
286	        }
287	        if (!hasValidNationalNumberLength(digits)) {
288	            return null;
289	        }
290	        return "+" + digits;
291	    }
292	
293	    /**
294	     * Format a stored E.164 telephone for human display: the country code, a space, then the
295	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
296	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
297	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
298	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
299	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
300	     * kept unchanged elsewhere.
301	     *
302	     * @param telephone the stored E.164 telephone, possibly {@code null}
303	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
304	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
305	     *     unchanged
306	     */
307	    public static String telephoneDisplay(String telephone) {
308	        if (telephone == null) {
309	            return null;
310	        }
311	        if (!telephone.matches("\\+\\d+")) {
312	            return telephone;
313	        }
314	        String digits = telephone.substring(1);
315	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
316	            if (digits.startsWith(countryCode)) {
317	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
318	            }
319	        }
320	        return "+" + groupDigits(digits);
321	    }
322	
323	    /**
324	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
325	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
326	     * {@code "412345678"} becomes {@code "412 345 678"}).
327	     *
328	     * @param digits the national digits
329	     * @return the space-grouped digits
330	     */
331	    private static String groupDigits(String digits) {
332	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
333	        for (int i = 0; i < digits.length(); i++) {
334	            if (i > 0 && i % 3 == 0) {
335	                grouped.append(' ');
336	            }
337	            grouped.append(digits.charAt(i));
338	        }
339	        return grouped.toString();
340	    }
341	
342	    /**
343	     * Required national-number length (the count of digits after the country code) for each
344	     * recognized country code, longest country code first so the prefix match is unambiguous.
345	     */
346	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
347	    static {
348	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
349	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
350	    }
351	
352	    /**
353	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
354	     * length its country code requires. A country code with no registered length places no
355	     * additional constraint and is accepted.
356	     *
357	     * @param digits the E.164 digits without the leading {@code '+'}
358	     * @return {@code true} if the national-number length is valid for the country code
359	     */
360	    private static boolean hasValidNationalNumberLength(String digits) {
361	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
362	            String countryCode = entry.getKey();
363	            if (digits.startsWith(countryCode)) {
364	                return digits.length() - countryCode.length() == entry.getValue();
365	            }
366	        }
367	        return true;
368	    }
369	
370	    /**
371	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
372	     * upper-cased abbreviation.
373	     */
374	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
375	        "ST", "STREET",
376	        "RD", "ROAD",
377	        "AVE", "AVENUE");
378	
379	    /**
380	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
381	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
382	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
383	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
384	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
385	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
386	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
387	     * value. The transform is idempotent: a normalized address normalizes to itself.
388	     *
389	     * @param address the raw address, possibly {@code null}
390	     * @return the normalized form, or {@code null} if the input was {@code null}
391	     */
392	    public static String normalizeAddress(String address) {
393	        if (address == null) {
394	            return null;
395	        }
396	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
397	        if (collapsed.isEmpty()) {
398	            return collapsed;
399	        }
400	        String[] tokens = collapsed.split(" ");
401	        StringBuilder normalized = new StringBuilder(collapsed.length());
402	        for (int i = 0; i < tokens.length; i++) {
403	            if (i > 0) {
404	                normalized.append(' ');
405	            }
406	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
407	        }
408	        return normalized.toString();
409	    }
410	
411	    /**
412	     * Normalize a household field (such as last name or address) to its canonical form for
413	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
414	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
415	     * that differ only in letter case or spacing are treated as the same value.
416	     *
417	     * @param value the raw field value, possibly {@code null}
418	     * @return the normalized form, or {@code null} if the input was {@code null}
419	     */
420	    public static String normalizeHousehold(String value) {
421	        if (value == null) {
422	            return null;
423	        }
424	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
425	    }
426	
427	    /**
428	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
429	     * last name (compared case-insensitively with collapsed whitespace, see
430	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
431	     * those two fields, so two owners who share a last name and postcode are assigned the same id
432	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
433	     * upper-cased hex characters of the SHA-256 digest of
434	     * {@code normalizedLastName + '|' + postcode}.
435	     *
436	     * @param lastName the owner's last name, possibly {@code null}
437	     * @param postcode the owner's postcode, possibly {@code null}
438	     * @return the household id, or {@code null} if either field is {@code null}
439	     */
440	    public static String householdId(String lastName, String postcode) {
441	        String normalizedLastName = normalizeHousehold(lastName);
442	        if (normalizedLastName == null || postcode == null) {
443	            return null;
444	        }
445	        String key = normalizedLastName + "|" + postcode;
446	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
447	    }
448	
449	    /**
450	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
451	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
452	     * so they all agree on algorithm and encoding.
453	     *
454	     * @param value the string to digest, never {@code null}
455	     * @return the 64-character lower-case hex digest
456	     */
457	    private static String sha256Hex(String value) {
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest(value.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder hex = new StringBuilder(digest.length * 2);
462	            for (byte b : digest) {
463	                hex.append(String.format("%02x", b));
464	            }
465	            return hex.toString();
466	        } catch (NoSuchAlgorithmException e) {
467	            // SHA-256 is a standard algorithm required to be present on every JVM.
468	            throw new IllegalStateException("SHA-256 not available", e);
469	        }
470	    }
471	
472	    /**
473	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
474	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
475	     * <ul>
476	     *   <li>{@code REGION} is the region code derived from the postcode (see
477	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
478	     *       in no known range, and</li>
479	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
480	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
481	     *       name.</li>
482	     * </ul>
483	     * The value is deterministic in the postcode, telephone and last name (e.g.
484	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
485	     *
486	     * @param postcode the owner's postcode, possibly {@code null}
487	     * @param telephone the owner's raw telephone, possibly {@code null}
488	     * @param lastName the owner's last name, possibly {@code null}
489	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
490	     */
491	    public static String customerCode(String postcode, String telephone, String lastName) {
492	        if (telephone == null || lastName == null) {
493	            return null;
494	        }
495	        String region = regionForPostcode(postcode);
496	        if (region == null) {
497	            region = "UNKNOWN";
498	        }
499	        String normalizedTelephone = normalizeTelephone(telephone);
500	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
501	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
502	    }
503	
504	    /**
505	     * Compute an owner's {@code identityKey}, the single derived value through which all
506	     * duplicate detection is now expressed. It consolidates the three formerly separate
507	     * telephone, email and household duplicate checks into one key, formatted as
508	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
509	     * <ul>
510	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
511	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
512	     *       when no email is present, and</li>
513	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
514	     * </ul>
515	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
516	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
517	     * members of the same household with different telephones have different keys.
518	     *
519	     * @param telephone the owner's raw telephone, possibly {@code null}
520	     * @param email the owner's email, possibly {@code null}
521	     * @param lastName the owner's last name, possibly {@code null}
522	     * @param postcode the owner's postcode, possibly {@code null}
523	     * @return the identity key, never {@code null}
524	     */
525	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
526	        String normalizedTelephone = normalizeTelephone(telephone);
527	        String normalizedEmail = normalizeEmail(email);
528	        String household = householdId(lastName, postcode);
529	        return (normalizedTelephone == null ? "" : normalizedTelephone)
530	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
531	            + "|" + (household == null ? "" : household);
532	    }
533	
534	    /**
535	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
536	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
537	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
538	     * value is deterministic in those two fields.
539	     *
540	     * @param customerCode the owner's customer code, possibly {@code null}
541	     * @param registrationDate the owner's registration date, possibly {@code null}
542	     * @return the membership number, or {@code null} if either field is {@code null}
543	     */
544	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
545	        if (customerCode == null || registrationDate == null) {
546	            return null;
547	        }
548	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
549	    }
550	
551	    /**
552	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
553	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
554	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
555	     * and gains 3 when the owner's tenure is more than 365 days (the tenure being the number of days
556	     * from {@code registrationDate} to today). Because a newly created owner has zero tenure, the
557	     * tenure points accrue only once the owner has been a member for over a year.
558	     *
559	     * @param namesakeCount the owner's namesake count, possibly {@code null}
560	     * @param email the owner's email, possibly {@code null}
561	     * @param householdCount the number of members in the owner's household, possibly {@code null}
562	     * @param registrationDate the owner's registration date, possibly {@code null}
563	     * @return the membership points, a non-negative integer
564	     */
565	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
566	            LocalDate registrationDate) {
567	        int points = 0;
568	        if (email != null && !email.isEmpty()) {
569	            points += 2;
570	        }
571	        if (namesakeCount != null && namesakeCount == 0) {
572	            points += 1;
573	        }
574	        if (householdCount != null && householdCount >= 3) {
575	            points += 2;
576	        }
577	        if (registrationDate != null
578	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365) {
579	            points += 3;
580	        }
581	        return points;
582	    }
583	
584	    /**
585	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
586	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
587	     *
588	     * @param membershipPoints the owner's membership points
589	     * @return the membership level, an integer from 1 to 4
590	     */
591	    public static int membershipLevel(int membershipPoints) {
592	        if (membershipPoints >= 6) {
593	            return 4;
594	        }
595	        if (membershipPoints >= 4) {
596	            return 3;
597	        }
598	        if (membershipPoints >= 2) {
599	            return 2;
600	        }
601	        return 1;
602	    }
603	
604	    /**
605	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
606	     * for postcode validation, keyed by the exact city name.
607	     */
608	    private static final Map<String, String> CITY_REGION = Map.of(
609	        "Sydney", "NSW",
610	        "Melbourne", "VIC",
611	        "Brisbane", "QLD");
612	
613	    /**
614	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
615	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
616	     * Because the customer code's region is itself derived from the postcode, the locality now shares
617	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
618	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
619	     *
620	     * @param customerCode the owner's customer code, possibly {@code null}
621	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
622	     */
623	    public static String locality(String customerCode) {
624	        if (customerCode == null) {
625	            return "UNKNOWN";
626	        }
627	        int dash = customerCode.indexOf('-');
628	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
629	    }
630	
631	    /**
632	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
633	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
634	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
635	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
636	     */
637	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
638	        "NSW", "Australia/Sydney",
639	        "VIC", "Australia/Melbourne",
640	        "QLD", "Australia/Brisbane");
641	
642	    /**
643	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
644	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
645	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
646	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
647	     * segment of the customer code. A region not in the table (including {@code 'UNKNOWN'}) has no
648	     * timezone and yields {@code null}.
649	     *
650	     * @param customerCode the owner's customer code, possibly {@code null}
651	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
652	     */
653	    public static String timezone(String customerCode) {
654	        return REGION_TIMEZONE.get(locality(customerCode));
655	    }
656	
657	    /**
658	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
659	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
660	     *
661	     * @param city the owner's city, possibly {@code null}
662	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
663	     */
664	    private static String regionForCity(String city) {
665	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
666	    }
667	
668	    /**
669	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
670	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
671	     * inclusive low and high bound of the region's valid 4-digit postcodes
672	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
673	     * table (including {@code 'UNKNOWN'}) places no range constraint.
674	     */
675	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
676	        "NSW", new int[] {2000, 2099},
677	        "VIC", new int[] {3000, 3099},
678	        "QLD", new int[] {4000, 4099});
679	
680	    /**
681	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
682	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
683	     * digits, or one that falls in no known range resolves to {@code null}.
684	     *
685	     * @param postcode the owner's postcode, possibly {@code null}
686	     * @return the matching region, or {@code null} when no range contains the postcode
687	     */
688	    private static String regionForPostcode(String postcode) {
689	        if (postcode == null || !postcode.matches("\\d{4}")) {
690	            return null;
691	        }
692	        int value = Integer.parseInt(postcode);
693	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
694	            int[] range = entry.getValue();
695	            if (value >= range[0] && value <= range[1]) {
696	                return entry.getKey();
697	            }
698	        }
699	        return null;
700	    }
701	
702	    /**
703	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
704	     * {@code null} or empty postcode is always valid. When present it must be exactly four
705	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
706	     * range the value must fall within that inclusive range. A city with no known region accepts
707	     * any four-digit postcode. This is the single source of
708	     * truth for postcode validity, shared by the DTO validation and any persistence path.
709	     *
710	     * @param postcode the owner's postcode, possibly {@code null}
711	     * @param city the owner's city, possibly {@code null}
712	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
713	     */
714	    public static boolean isPostcodeValidForCity(String postcode, String city) {
715	        if (postcode == null || postcode.isEmpty()) {
716	            return true;
717	        }
718	        if (!postcode.matches("\\d{4}")) {
719	            return false;
720	        }
721	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
722	        if (range == null) {
723	            return true;
724	        }
725	        int value = Integer.parseInt(postcode);
726	        return value >= range[0] && value <= range[1];
727	    }
728	
729	    /**
730	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
731	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
732	     * value is deterministic in the customer code and is the standard Luhn check digit: each
733	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
734	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
735	     * brings the weighted sum up to the next multiple of ten.
736	     *
737	     * @param customerCode the owner's customer code, possibly {@code null}
738	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
739	     */
740	    public static Integer checkDigit(String customerCode) {
741	        if (customerCode == null) {
742	            return null;
743	        }
744	        int sum = 0;
745	        boolean dbl = true;
746	        for (int i = customerCode.length() - 1; i >= 0; i--) {
747	            char c = customerCode.charAt(i);
748	            if (c < '0' || c > '9') {
749	                continue;
750	            }
751	            int d = c - '0';
752	            if (dbl) {
753	                d *= 2;
754	                if (d > 9) {
755	                    d -= 9;
756	                }
757	            }
758	            sum += d;
759	            dbl = !dbl;
760	        }
761	        return (10 - (sum % 10)) % 10;
762	    }
763	
764	    /**
765	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
766	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
767	     * is deterministic in the email.
768	     *
769	     * @param email the owner's email, possibly {@code null}
770	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
771	     */
772	    public static String contactPreference(String email) {
773	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
774	    }
775	
776	    /**
777	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
778	     * date. The age in whole years is the number of completed years between {@code birthDate} and
779	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
780	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
781	     * two fields and is only defined when both are present.
782	     *
783	     * @param birthDate the owner's date of birth, possibly {@code null}
784	     * @param registrationDate the owner's registration date, possibly {@code null}
785	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
786	     *     is {@code null}
787	     */
788	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
789	        if (birthDate == null || registrationDate == null) {
790	            return null;
791	        }
792	        int age = Period.between(birthDate, registrationDate).getYears();
793	        if (age < 18) {
794	            return "MINOR";
795	        }
796	        if (age < 65) {
797	            return "ADULT";
798	        }
799	        return "SENIOR";
800	    }
801	
802	    protected Set<Pet> getPetsInternal() {
803	        if (this.pets == null) {
804	            this.pets = new HashSet<>();
805	        }
806	        return this.pets;
807	    }
808	
809	    protected void setPetsInternal(Set<Pet> pets) {
810	        this.pets = pets;
811	    }
812	
813	    public List<Pet> getPets() {
814	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
815	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
816	        return Collections.unmodifiableList(sortedPets);
817	    }
818	
819	    public void setPets(List<Pet> pets) {
820	        this.pets = new HashSet<>(pets);
821	    }
822	
823	    public void addPet(Pet pet) {
824	        getPetsInternal().add(pet);
825	        pet.setOwner(this);
826	    }
827	
828	    /**
829	     * Return the Pet with the given name, or null if none found for this Owner.
830	     *
831	     * @param name to test
832	     * @return true if pet name is already in use
833	     */
834	    public Pet getPet(String name) {
835	        return getPet(name, false);
836	    }
837	
838	    /**
839	     * Return the Pet with the given name, or null if none found for this Owner.
840	     *
841	     * @param name to test
842	     * @return true if pet name is already in use
843	     */
844	    public Pet getPet(String name, boolean ignoreNew) {
845	        name = name.toLowerCase();
846	        for (Pet pet : getPetsInternal()) {
847	            if (!ignoreNew || !pet.isNew()) {
848	                String compName = pet.getName();
849	                compName = compName.toLowerCase();
850	                if (compName.equals(name)) {
851	                    return pet;
852	                }
853	            }
854	        }
855	        return null;
856	    }
857	
858	    public Pet getPet(Integer petId) {
859	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
860	    }
861	
862	    @Override
863	    public String toString() {
864	        return new ToStringCreator(this)
865	
866	            .append("id", this.getId())
867	            .append("new", this.isNew())
868	            .append("lastName", this.getLastName())
869	            .append("firstName", this.getFirstName())
870	            .append("address", this.address)
871	            .append("city", this.city)
872	            .append("telephone", this.telephone)
873	            .toString();
874	    }
875	}
